// Chord Diagram — Network, route: jsx
// Source: chord-diagram
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

/** Survey of 1,064 companies: rows are the current provider, columns the previous one. */
const providers = ['AWS', 'Azure', 'GCP', 'Oracle', 'IBM', 'Alibaba', 'Other'];

const migrations: number[][] = [
  [320, 14, 11, 21, 15, 4, 26],
  [18, 210, 13, 17, 14, 3, 21],
  [22, 16, 120, 9, 7, 3, 15],
  [3, 2, 1, 26, 2, 1, 2],
  [2, 3, 1, 2, 18, 1, 2],
  [4, 2, 2, 1, 1, 22, 3],
  [9, 7, 5, 4, 3, 2, 34]
];

/** A square flow matrix and the name of each of its rows: `matrix[i][j]` runs from j to i. */
export type Data = { names: string[]; matrix: number[][] };

const DEMO: Data = { names: providers, matrix: migrations };

const MAX_SIZE = 560;
/** Room outside the arcs for tick marks, tick labels and the rotated group names. */
const MARGIN = 88;
const ARC_THICKNESS = 10;
const LABEL_EVERY = 5;

const formatTick = d3.format('~s');
const formatCount = d3.format(',');

type GroupTick = { value: number; angle: number };

function groupTicks(group: d3.ChordGroup, tickStep: number): GroupTick[] {
  const k = (group.endAngle - group.startAngle) / group.value;
  return d3.range(0, group.value, tickStep).map((value) => ({
    value,
    angle: value * k + group.startAngle
  }));
}

function describe(chord: d3.Chord, names: string[]): string {
  const to = names[chord.source.index];
  const from = names[chord.target.index];
  if (chord.source.index === chord.target.index) {
    return `${formatCount(chord.source.value)} stayed on ${to}`;
  }
  return [
    `${formatCount(chord.source.value)} moved ${from} → ${to}`,
    `${formatCount(chord.target.value)} moved ${to} → ${from}`
  ].join('\n');
}

export default function ChordDiagram({ data = DEMO, width }: { data?: Data; width: number }) {
  const { names, matrix } = data;
  const height = Math.min(width, MAX_SIZE);
  const outerRadius = Math.max(Math.min(width, height) / 2 - MARGIN, 40);
  const innerRadius = outerRadius - ARC_THICKNESS;

  // Ruler graduation, derived from the grand total so every arc shares one scale.
  const tickStep = useMemo(
    () => d3.tickStep(0, d3.sum(matrix, (row) => d3.sum(row)), 40),
    [matrix]
  );

  const chords = useMemo(
    () => d3.chord().padAngle(10 / innerRadius).sortSubgroups(d3.descending).sortChords(d3.descending)(matrix),
    [matrix, innerRadius]
  );

  const arc = useMemo(
    () => d3.arc<d3.ChordGroup>().innerRadius(innerRadius).outerRadius(outerRadius),
    [innerRadius, outerRadius]
  );

  // @types/d3-chord declares a void-returning overload first, so the path-string
  // signature has to be pinned by the annotation.
  const ribbon = useMemo<(chord: d3.Chord) => string | null>(
    () =>
      d3
        .ribbon<d3.Chord, d3.ChordSubgroup>()
        .radius(innerRadius - 1)
        .padAngle(1 / innerRadius),
    [innerRadius]
  );

  const color = useMemo(
    () => d3.scaleOrdinal<string, string>().domain(names).range(d3.schemeObservable10),
    [names]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`${-width / 2} ${-height / 2} ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Chord diagram of cloud provider migration among surveyed companies"
    >
      {chords.groups.map((group) => {
        const name = names[group.index];
        const midAngle = (group.startAngle + group.endAngle) / 2;
        const isLeftHalf = midAngle > Math.PI;
        return (
          <g key={name}>
            <path d={arc(group) ?? undefined} fill={color(name)}>
              <title>{`${name}\n${formatCount(group.value)} companies`}</title>
            </path>

            <g fontSize={9} fill="var(--muted)">
              {groupTicks(group, tickStep).map((tick, i) => (
                <g
                  key={tick.value}
                  transform={`rotate(${(tick.angle * 180) / Math.PI - 90}) translate(${outerRadius},0)`}
                >
                  <line x2={6} stroke="var(--muted)" />
                  {i % LABEL_EVERY === 0 && (
                    <text
                      x={8}
                      dy="0.35em"
                      transform={tick.angle > Math.PI ? 'rotate(180) translate(-16)' : undefined}
                      textAnchor={tick.angle > Math.PI ? 'end' : undefined}
                    >
                      {formatTick(tick.value)}
                    </text>
                  )}
                </g>
              ))}
            </g>

            <g
              fontSize={11}
              fontWeight="bold"
              fill="var(--text)"
              transform={`rotate(${(midAngle * 180) / Math.PI - 90}) translate(${outerRadius + 34},0)`}
            >
              <text
                dy="0.35em"
                transform={isLeftHalf ? 'rotate(180)' : undefined}
                textAnchor={isLeftHalf ? 'end' : undefined}
              >
                {name}
              </text>
            </g>
          </g>
        );
      })}

      {/* Chords sit inside the arcs, so they are drawn last and kept translucent. */}
      <g fillOpacity={0.75}>
        {chords.map((chord) => (
          <path
            key={`${chord.source.index}-${chord.target.index}`}
            d={ribbon(chord) ?? undefined}
            fill={color(names[chord.source.index])}
            stroke="var(--bg)"
            strokeWidth={0.4}
          >
            <title>{describe(chord, names)}</title>
          </path>
        ))}
      </g>
    </svg>
  );
}
